import { isRequest, message, type NativeCall, type Schema, type WorkerResponse } from './protocol.js';
import type { ResultType } from '../model/value-types.js';

export interface WorkerScope {
  postMessage(message: WorkerResponse): void;
  onmessage: ((event: MessageEvent<unknown>) => void) | null;
}
// Code generated by wasmgen. DO NOT EDIT.
function check(value: unknown, type: ResultType, at: string): void {
  if (type === 'void') return;
  if (type.endsWith('[]')) {
    if (!Array.isArray(value)) throw new TypeError(`${at}: expected ${type}`);
    for (let index = 0; index < value.length; index++) check(value[index], type.slice(0, -2) as ResultType, `${at}[${index}]`);
    return;
  }
  let valid;
  switch (type) {
    case 'string': valid = typeof value === 'string'; break;
    case 'bool': valid = typeof value === 'boolean'; break;
    case 'f64': valid = typeof value === 'number' && Number.isFinite(value); break;
    case 'i32': valid = typeof value === 'number' && Number.isInteger(value) && value >= -2147483648 && value <= 2147483647; break;
    case 'u32': valid = typeof value === 'number' && Number.isInteger(value) && value >= 0 && value <= 4294967295; break;
    default: throw new TypeError(`unsupported type ${type}`);
  }
  if (!valid) throw new TypeError(`${at}: expected ${type}`);
}

export async function serve(initialize: () => Promise<NativeCall>, schema: Schema, scope: WorkerScope = self): Promise<void> {
  let call: NativeCall;
  try { call = await initialize(); }
  catch (error) { scope.postMessage({ type: 'fatal', error: message(error) }); return; }
  let queue = Promise.resolve();
  let failed = false;
  scope.onmessage = ({ data }) => {
    if (failed) return;
    if (!isRequest(data)) { failed = true; scope.postMessage({ type: 'fatal', error: 'invalid worker request' }); return; }
    // Await native Promises without letting later calls overtake earlier ones.
    queue = queue.then(async () => {
    if (failed) return;
    const { id, method, args } = data;
    try {
      if (!Object.hasOwn(schema, method) || !schema[method]) throw new Error(`unknown function ${method}`);
      const fn = schema[method];
      if (!Array.isArray(args) || args.length !== fn.params.length) throw new TypeError(`${method}: expected ${fn.params.length} arguments`);
      fn.params.forEach((param, index) => check(args[index], param.type, `${method}.${param.name}`));
      const result = await call(method, args);
      if (!result.ok) throw new Error(result.error);
      // nil Go slices encode as null; the public array contract always returns [].
      const value = fn.result.endsWith('[]') && result.value === null ? [] : result.value;
      check(value, fn.result, `${method} result`);
      scope.postMessage({ type: 'result', id, ok: true, value: fn.result === 'void' ? undefined : value });
    } catch (error) {
      if (error instanceof WebAssembly.RuntimeError) {
        failed = true;
        scope.postMessage({ type: 'fatal', error: error.message });
      } else {
        scope.postMessage({ type: 'result', id, ok: false, error: message(error) });
      }
    }
    }).catch((error: unknown) => { failed = true; scope.postMessage({ type: 'fatal', error: message(error) }); });
  };
  scope.postMessage({ type: 'ready' });
}
